/**
 * 測試用：2026 年 10 月醫師看診表（依診所配置表轉錄），系統已不使用。
 * 名字加括號＝有看診但不開放一般約診。
 * assistantsNeeded 是配置表上該診的助理需求人數，目前只記錄，尚未用於排班規則。
 */

import { doctorIdsByName, type ClinicClosure, type DoctorSession } from "@/config/doctors";

const SHIFT_IDS = { 早: "morning", 午: "afternoon", 晚: "evening" } as const;

// 例："10-07 午 11 張雅文 吳宗翰 劉怡萱 (陳美玲)"
function session(line: string): DoctorSession {
  const [monthDay, shift, needed, ...names] = line.split(" ");
  return {
    date: `2026-${monthDay}`,
    shiftId: SHIFT_IDS[shift as keyof typeof SHIFT_IDS],
    assistantsNeeded: Number(needed),
    doctors: names.map((raw) => {
      const limitedBooking = raw.startsWith("(");
      const name = raw.replace(/[()]/g, "");
      return { personId: doctorIdsByName[name], limitedBooking };
    }),
  };
}

